import{isInactiveWorkflowRunError}from"#internal/workflow/is-inactive-workflow-run-error.js";import{cancelRun}from"#internal/workflow/runtime.js";async function cancelExpiredDevelopmentRun(e,t){try{let n=await e.runs.get(t,{resolveData:`none`});if(n.status!==`pending`&&n.status!==`running`)return;try{await cancelRun(e,t,{cancelReason:`Development runtime snapshot is no longer available`})}catch(n){if(isInactiveWorkflowRunError(n))return;let r=await e.runs.get(t,{resolveData:`none`});if(r.status===`pending`||r.status===`running`)throw n}}catch(e){if(!isInactiveWorkflowRunError(e))throw e}}export{cancelExpiredDevelopmentRun};